'use strict';
const {test,expect}=require('@playwright/test');
const {DIALOGUE}=require('../support/unit9-10-flow');
test.use({reducedMotion:'reduce',actionTimeout:5000});
async function observe(page){await page.addInitScript(()=>{window.nativePlays=[];const play=HTMLMediaElement.prototype.play;HTMLMediaElement.prototype.play=function(...args){const entry={src:this.src,ended:false};window.nativePlays.push(entry);this.addEventListener('ended',()=>{entry.ended=true;},{once:true});return Reflect.apply(play,this,args);};});}
async function heard(page,control,path){const before=await page.evaluate(()=>window.nativePlays.length);await control.click();await expect.poll(()=>page.evaluate(({before,path})=>window.nativePlays.slice(before).some(x=>new URL(x.src).pathname===path&&x.ended),{before,path}),{timeout:15000}).toBe(true);}
const WORDS=['hello','hi','how','today','well','fine','thanks','goodbye','see','fat','woman','thin','tall','short','dirty','clean','hot','cold','old','young','busy','lazy'];
const MODELS=["Look at that man! He's very fat.","Look at that woman! She's very thin.","Look at that policeman! He's very tall.","Look at that policewoman! She's very short.","Look at that mechanic! He's very dirty.","Look at that nurse! She's very clean.","Look at Steven! He's very hot.","Look at Emma! She's very cold.","Look at that milkman! He's very old.","Look at that air hostess! She's very young.","Look at that hairdresser! He's very busy.","Look at that housewife! She's very lazy."];
const REFERENCES=["Robert isn't a teacher. He's an engineer.","Mr. Blake isn't a student. He's a teacher.","This isn't my umbrella. It's your umbrella.","Sophie isn't a teacher. She's a keyboard operator.","Steven isn't cold. He's hot.","Naoko isn't Chinese. She's Japanese.","This isn't a German car. It's a Swedish car."];
test('57 段录音全部从对应页面原生播放结束；原文、图示和书面示范逐条对应',async({page})=>{
 test.setTimeout(300000);await observe(page);const failed=[];page.on('response',r=>{if(r.status()>=400)failed.push(r.url());});await page.goto('/unit9-10/#learn/words');const words=page.locator('.stage-words');
 for(let i=0;i<WORDS.length;i++){if(i&&i%6===0)await words.getByRole('button',{name:'下一组词卡',exact:true}).click();await heard(page,words.getByRole('button',{name:WORDS[i],exact:true}),'/unit9-10/audio/'+(i<9?'l09-w'+String(i+1).padStart(2,'0'):'l10-w'+String(i-8).padStart(2,'0'))+'.mp3');}
 await page.getByRole('link',{name:'街角遇见朋友',exact:true}).click();const story=page.locator('.stage-text');
 for(let i=0;i<14;i++){await heard(page,story.getByRole('button',{name:i?'下一句':'开始听课文',exact:true}),'/unit9-10/audio/l09-d'+String(i+1).padStart(2,'0')+'.mp3');await expect(story.locator('.btext span')).toHaveText(DIALOGUE.slice(0,i+1));}
 await story.getByRole('button',{name:'完成课文学习',exact:true}).click();await page.getByRole('link',{name:'把关心接下去',exact:true}).click();const phrases=page.locator('.stage-phrases');
 for(const [text,file]of [['How are you today?','03'],["I'm very well, thank you.",'04'],['And you?','05'],['Nice to see you.','12']])await heard(page,phrases.getByRole('button',{name:text,exact:true}),'/unit9-10/audio/l09-d'+file+'.mp3');
 await page.getByRole('link',{name:'看一看，说一说',exact:true}).click();const models=page.locator('.stage-models');await heard(page,models.getByRole('button',{name:"Look at Helen. She's very well.",exact:true}),'/unit9-10/audio/l10-b00.mp3');
 for(let i=0;i<12;i++)await heard(page,models.getByRole('button',{name:MODELS[i],exact:true}),'/unit9-10/audio/l10-b'+String(i+1).padStart(2,'0')+'.mp3');
 await models.getByText('换个说法，说清楚',{exact:true}).click();for(let i=0;i<7;i++)await heard(page,models.getByRole('button',{name:REFERENCES[i],exact:true}),'/unit9-10/audio/written-a-'+String(i).padStart(2,'0')+'.mp3');
 await page.getByRole('link',{name:'暖心小伙伴',exact:true}).click();await heard(page,page.locator('.stage-exam').getByRole('button',{name:'听一遍',exact:true}),'/unit9-10/audio/challenge-tony.mp3');
 expect(await page.evaluate(()=>new Set(window.nativePlays.filter(x=>x.ended&&x.src.includes('/unit9-10/audio/')).map(x=>new URL(x.src).pathname)).size)).toBe(57);expect(failed).toEqual([]);
});
test('子目录音频失败不放行，恢复后可重听、错答重选，正误音效沿用公共方案',async({page})=>{
 test.setTimeout(60000);await observe(page);let fail=true;await page.route('**/unit9-10/audio/l10-w02.mp3',r=>fail?r.abort():r.continue());await page.goto('/lesson/unit9-10/#learn/listen');const room=page.locator('.stage-listen');await room.getByRole('button',{name:'woman',exact:true}).click();await room.getByRole('button',{name:'听一遍',exact:true}).click();await expect(room).toContainText('播放未完成，请重听。');await expect(room.getByRole('button',{name:'检查答案',exact:true})).toBeDisabled();fail=false;
 await heard(page,room.getByRole('button',{name:'再听一遍',exact:true}),'/lesson/unit9-10/audio/l10-w02.mp3');await room.getByRole('button',{name:'fat',exact:true}).click();await heard(page,room.getByRole('button',{name:'检查答案',exact:true}),'/lesson/assets/feedback/duolingo-incorrect.mp3');await expect(room.getByRole('progressbar')).toHaveAttribute('aria-valuenow','0');
 await room.getByRole('button',{name:'再试一次',exact:true}).click();await room.getByRole('button',{name:'woman',exact:true}).click();await heard(page,room.getByRole('button',{name:'听一遍',exact:true}),'/lesson/unit9-10/audio/l10-w02.mp3');await heard(page,room.getByRole('button',{name:'检查答案',exact:true}),'/lesson/assets/feedback/duolingo-correct.mp3');await expect(room.getByRole('progressbar')).toHaveAttribute('aria-valuenow','1');await expect(room.getByRole('button',{name:'给点线索',exact:true})).toHaveCount(0);
});
test('历史句重听、中文和离开活动都不能代替当前句；固定对白区域保留所有旧句',async({page})=>{
 test.setTimeout(60000);await observe(page);await page.goto('/unit9-10/#learn/text');const room=page.locator('.stage-text');await heard(page,room.getByRole('button',{name:'开始听课文',exact:true}),'/unit9-10/audio/l09-d01.mp3');await room.getByRole('button',{name:'下一句',exact:true}).click();await heard(page,room.getByRole('button',{name:DIALOGUE[0],exact:true}),'/unit9-10/audio/l09-d01.mp3');await expect(room.getByRole('button',{name:'下一句',exact:true})).toBeDisabled();await room.locator('.bubble-row').first().getByRole('button',{name:'看中文',exact:true}).click();await expect(room.locator('.bubble-row').first()).toContainText('你好，海伦。');await expect(room.getByRole('button',{name:'下一句',exact:true})).toBeDisabled();
 await heard(page,room.getByRole('button',{name:DIALOGUE[1],exact:true}),'/unit9-10/audio/l09-d02.mp3');await room.getByRole('button',{name:'下一句',exact:true}).click();await page.getByRole('link',{name:'把关心接下去',exact:true}).click();await page.getByRole('link',{name:'街角遇见朋友',exact:true}).click();await expect(room.getByRole('button',{name:'下一句',exact:true})).toBeDisabled();await heard(page,room.getByRole('button',{name:DIALOGUE[2],exact:true}),'/unit9-10/audio/l09-d03.mp3');await expect(room.getByRole('button',{name:'下一句',exact:true})).toBeEnabled();await expect(room.locator('.bubble-row')).toHaveCount(3);
});
